// ============================================
// Contact.jsx - Contact Page (Strategy Style)
// Real working form via Formspree (replaces the old, broken mailto flow)
// ============================================
import React, { useState } from 'react';
import Seo from '../components/Seo';
import { useOwnerDetails } from '../App';
import OferWhite from '../assets/images/oferWhite.jpg';
import '../styles/contact-form.css';

// 1) Create a free form at https://formspree.io  ->  copy your form ID
// 2) Put it in .env as REACT_APP_FORMSPREE_ID=xxxxxxx  (or paste it below)
const FORMSPREE_ENDPOINT = `https://formspree.io/f/${process.env.REACT_APP_FORMSPREE_ID || 'YOUR_FORM_ID'}`;

function Contact() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: 'General Inquiry',
    message: ''
  });
  const [status, setStatus] = useState('idle'); // idle | submitting | success | error

  // Get contact and social data from Firebase
  const { contact, social, loading } = useOwnerDetails();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus('submitting');
    try {
      const res = await fetch(FORMSPREE_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          name: formData.name,
          email: formData.email,
          subject: formData.subject,
          message: formData.message,
          _subject: `[${formData.subject}] Message from ${formData.name}`
        })
      });
      if (res.ok) {
        setStatus('success');
        setFormData({ name: '', email: '', subject: 'General Inquiry', message: '' });
      } else {
        setStatus('error');
      }
    } catch (err) {
      setStatus('error');
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Contact methods using Firebase data
  const contactMethods = [
    {
      icon: '✉️',
      title: 'Email',
      desc: 'Detailed inquiries',
      value: contact.email,
      link: `https://mail.google.com/mail/?view=cm&fs=1&to=${contact.email}`,
      colorClass: 'email'
    },
    {
      icon: '💬',
      title: 'WhatsApp',
      desc: 'Fastest response',
      value: contact.whatsapp,
      link: contact.whatsapp ? `https://wa.me/${contact.whatsapp.replace('+', '')}` : '#',
      colorClass: 'whatsapp'
    },
    {
      icon: '📺',
      title: 'YouTube',
      desc: 'Free education',
      value: 'OferWaron97Gold',
      link: social.youtube,
      colorClass: 'youtube'
    }
  ];

  if (loading) {
    return (
      <div className="strategy-page">
        <section className="strategy-section text-center">
          <p className="strategy-subtitle">Loading contact information...</p>
        </section>
      </div>
    );
  }

  return (
    <div className="strategy-page">
      <Seo
        title="Contact — Get in Touch | 97% Gold"
        description="Contact 97% Gold about XAUUSD trading signals. Reach out via WhatsApp for the fastest response, or email for detailed inquiries."
        path="/contact"
        ogType="website"
      />

      {/* Hero with Image */}
      <section className="strategy-section text-center">
        <h1 className="get-in-touch-title get-in-touch-title--shimmer">
          <span className="get-in-touch-shimmer">
          Get in Touch
            <span className="sparkle sparkle-1">✦</span>
            <span className="sparkle sparkle-2">✦</span>
          </span>
        </h1>

        {/* Contact Hero Image */}
        <div className="contact-hero-image-wrapper">
          <div className="contact-hero-image-container">
            <img
              src={OferWhite}
              alt="Ofer Waron - Ready to help"
              className="contact-hero-image"
            />
            <div className="contact-hero-image-glow"></div>
          </div>
        </div>

        <p className="strategy-subtitle contact-hero-subtitle">
          Have questions? I'd love to hear from you.<br />
          Send me a message and I'll respond as soon as possible.
        </p>
      </section>

      {/* Contact Methods - Strategy Card Style */}
      <section className="strategy-section">
        <div className="strategy-card-grid">
          {contactMethods.map((method, i) => (
            <a
              key={i}
              href={method.link}
              target={method.link.startsWith('mailto:') ? '_self' : '_blank'}
              rel={method.link.startsWith('mailto:') ? undefined : 'noopener noreferrer'}
              className={`strategy-rule-card contact-method-card contact-method-${method.colorClass}`}
              style={{ textDecoration: 'none', cursor: 'pointer' }}
            >
              <div className="strategy-rule-icon">{method.icon}</div>
              <h3 className="strategy-rule-title">{method.title}</h3>
              <p className="strategy-rule-desc">{method.desc}</p>
              <p className="contact-method-value">{method.value}</p>
            </a>
          ))}
        </div>
      </section>

      {/* Real working contact form */}
      <section className="strategy-section">
        <div className="contact-form-wrapper" style={{ maxWidth: 560, margin: '0 auto' }}>
          {status === 'success' ? (
            <div className="strategy-rule-card text-center" role="status">
              <div className="strategy-rule-icon">✅</div>
              <h3 className="strategy-rule-title">Message sent</h3>
              <p className="strategy-rule-desc">Thanks — I'll get back to you soon.</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="contact-form" noValidate>
              <div className="contact-form-row">
                <label htmlFor="cf-name" className="contact-form-label">Name</label>
                <input
                  id="cf-name" name="name" type="text" required
                  value={formData.name} onChange={handleChange}
                  className="contact-form-input" autoComplete="name"
                />
              </div>

              <div className="contact-form-row">
                <label htmlFor="cf-email" className="contact-form-label">Email</label>
                <input
                  id="cf-email" name="email" type="email" required
                  value={formData.email} onChange={handleChange}
                  className="contact-form-input" autoComplete="email"
                />
              </div>

              <div className="contact-form-row">
                <label htmlFor="cf-subject" className="contact-form-label">Subject</label>
                <select
                  id="cf-subject" name="subject"
                  value={formData.subject} onChange={handleChange}
                  className="contact-form-input"
                >
                  <option>General Inquiry</option>
                  <option>Free Trial</option>
                  <option>Subscription</option>
                  <option>Technical Support</option>
                </select>
              </div>

              <div className="contact-form-row">
                <label htmlFor="cf-message" className="contact-form-label">Message</label>
                <textarea
                  id="cf-message" name="message" rows={5} required
                  value={formData.message} onChange={handleChange}
                  className="contact-form-input"
                />
              </div>

              {status === 'error' && (
                <p className="contact-form-error" role="alert" style={{ color: '#ff6b6b' }}>
                  Something went wrong. Please try WhatsApp or email above.
                </p>
              )}

              <button
                type="submit"
                className="strategy-btn strategy-btn-primary"
                disabled={status === 'submitting'}
              >
                {status === 'submitting' ? 'Sending…' : 'Send Message'}
              </button>
            </form>
          )}
        </div>
      </section>
    </div>
  );
}

export default Contact;
